import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import { MAX_ATTEMPTS, RETRY_DELAY_MS, STEP_MS, TRANSIENT_ERROR, type JobRow } from './jobs.ts';

const HEARTBEAT_MS = 1000;
const IDLE_POLL_MS = 200;

const db = openDatabase();

const heartbeat = db.prepare(`
  INSERT INTO heartbeats (name, at) VALUES ('worker', ?)
  ON CONFLICT (name) DO UPDATE SET at = excluded.at`);
const clearHeartbeat = db.prepare("DELETE FROM heartbeats WHERE name = 'worker'");
// A job left "running" means an earlier worker died mid-attempt: put it back in the queue.
const requeueInterrupted = db.prepare(`
  UPDATE jobs SET status = 'queued', progress_completed = 0, available_at = ?, updated_at = ?
  WHERE status = 'running'`);
const nextQueued = db.prepare(`
  SELECT * FROM jobs WHERE status = 'queued' AND available_at <= ? ORDER BY seq LIMIT 1`);
const claim = db.prepare(`
  UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ?
  WHERE id = ? AND status = 'queued'`);
const setProgress = db.prepare(`
  UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ? AND status = 'running'`);
const complete = db.prepare(`
  UPDATE jobs SET status = 'completed', progress_completed = steps, result_output = ?, error = NULL, updated_at = ?
  WHERE id = ? AND status = 'running'`);
const requeue = db.prepare(`
  UPDATE jobs SET status = 'queued', progress_completed = 0, available_at = ?, updated_at = ?
  WHERE id = ? AND status = 'running'`);
const fail = db.prepare(`
  UPDATE jobs SET status = 'failed', progress_completed = 0, result_output = NULL, error = ?, updated_at = ?
  WHERE id = ? AND status = 'running'`);

let stopping = false;
const stop = (): void => {
  stopping = true;
};
process.on('SIGTERM', stop);
process.on('SIGINT', stop);

const nowIso = (): string => new Date().toISOString();

function beat(): void {
  heartbeat.run(Date.now());
}

/** Runs one attempt of a claimed job. Returns early, leaving the job running, if the worker is stopping. */
async function runAttempt(job: JobRow, attempt: number): Promise<void> {
  if (attempt <= job.fail_attempts) {
    // Simulated transient failure: fails at the first step, before any progress.
    await sleep(STEP_MS);
    if (attempt >= MAX_ATTEMPTS) fail.run(TRANSIENT_ERROR, nowIso(), job.id);
    else requeue.run(Date.now() + RETRY_DELAY_MS, nowIso(), job.id);
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return;
    setProgress.run(step, nowIso(), job.id);
  }
  complete.run(job.input.toUpperCase(), nowIso(), job.id);
}

async function main(): Promise<void> {
  requeueInterrupted.run(Date.now(), nowIso());
  beat();
  const timer = setInterval(beat, HEARTBEAT_MS);

  console.log('worker started');
  while (!stopping) {
    const job = nextQueued.get(Date.now()) as JobRow | undefined;
    if (!job) {
      await sleep(IDLE_POLL_MS);
      continue;
    }
    const claimed = claim.run(nowIso(), job.id);
    if (Number(claimed.changes) === 0) continue;
    await runAttempt(job, job.attempts + 1);
  }

  clearInterval(timer);
  clearHeartbeat.run();
  db.close();
  console.log('worker stopped');
  process.exit(0);
}

main().catch((e: unknown) => {
  console.error('worker failed:', e);
  process.exit(1);
});

